import json

# Pretend CloudTrail events for the last 90 days: (action, resource ARN)
events = [
    ("s3:GetObject", "arn:aws:s3:::reports/2024/a.csv"),
    ("s3:GetObject", "arn:aws:s3:::reports/2024/b.csv"),
    ("s3:PutObject", "arn:aws:s3:::reports/out/c.csv"),
    ("sqs:SendMessage", "arn:aws:sqs:eu-west-1:123456789012:jobs"),
]
print("old policy: Action * on Resource *")

def prefix(arn):
    # tighten an object ARN to its first folder: .../reports/2024/*
    if arn.startswith("arn:aws:s3:::"):
        bucket, _, rest = arn[len("arn:aws:s3:::"):].partition("/")
        return "arn:aws:s3:::%s/%s/*" % (bucket, rest.split("/")[0])
    return arn

grouped = {}
for action, arn in events:
    grouped.setdefault(prefix(arn), set()).add(action)

policy = {"Statement": [
    {"Effect": "Allow", "Action": sorted(acts), "Resource": res}
    for res, acts in sorted(grouped.items())]}
print(json.dumps(policy, indent=1))
