from fnmatch import fnmatchcase

# Trust policy conditions for a GitHub Actions deploy role
trust = {"aud": "sts.amazonaws.com", "sub": "repo:acme/shop:ref:refs/heads/main"}
loose = {"aud": "sts.amazonaws.com", "sub": "repo:acme/*"}  # the common mistake

def can_assume(token, cond):
    # StringEquals / StringLike style check of every claim
    return all(fnmatchcase(token.get(k, ""), v) for k, v in cond.items())

tokens = [
    {"aud": "sts.amazonaws.com", "sub": "repo:acme/shop:ref:refs/heads/main"},
    {"aud": "sts.amazonaws.com", "sub": "repo:acme/shop:ref:refs/heads/feature-x"},
    {"aud": "sts.amazonaws.com", "sub": "repo:acme/other:ref:refs/heads/main"},
]
for t in tokens:
    print(t["sub"], "strict:", can_assume(t, trust), "loose:", can_assume(t, loose))

import ipaddress

# Route tables: the most specific (longest) matching prefix wins
public = {"10.20.0.0/16": "local", "0.0.0.0/0": "igw-1"}
private = {"10.20.0.0/16": "local", "0.0.0.0/0": "nat-a"}
isolated = {"10.20.0.0/16": "local"}

def route(table, dest):
    ip = ipaddress.ip_address(dest)
    matches = [(ipaddress.ip_network(p), t) for p, t in table.items()
               if ip in ipaddress.ip_network(p)]
    if not matches:
        return "no route (dropped)"
    return max(matches, key=lambda m: m[0].prefixlen)[1]

for name, table in [("public", public), ("private", private), ("data", isolated)]:
    for dest in ["10.20.5.9", "93.184.216.34"]:
        print("%-7s -> %-14s via %s" % (name, dest, route(table, dest)))
